@staticmethod
def valid_asset_commit_intent(operation_id: str, intent: object) -> bool:
    """校验提交意图是否具备安全回滚/前滚所需的全部标识与整数。

    正常提交写入的意图含 operation_id/asset_id/delta、提交前资产
    快照 old_asset（None 或 {balance,version}）、pending 操作记录、
    提交结果 new_balance/new_version；报告触发的提交另带可选键
    report（达门槛报告 B）。任一字段缺失、类型错误、布尔
    冒整、标识不匹配或前后账目不守恒都判定为无效：调用方必须
    fail-closed（保留意图现场，不回滚/前滚/清理），绝不把损坏意图
    当成空意图继续。
    """
    if not isinstance(intent, dict):
        return False
    if intent.get("operation_id") != operation_id:
        return False
    asset_id = intent.get("asset_id")
    if not _valid_safe_id(asset_id):
        return False
    delta = intent.get("delta")
    if not _is_plain_int(delta) or delta == 0:
        return False
    new_balance = intent.get("new_balance")
    new_version = intent.get("new_version")
    if not _is_plain_int(new_balance) or not _is_plain_int(new_version):
        return False
    old_asset = intent.get("old_asset")
    if old_asset is not None and not _asset_entry_shape_ok(old_asset):
        return False
    pending = intent.get("pending")
    if not _asset_operation_shape_ok(operation_id, pending):
        return False
    # pending 是创建时刻的操作快照 R，服务正常写入必带非布尔整数
    # balance/version；恢复据此还原操作，缺失即不可安全对账。
    if not _is_plain_int(pending.get("balance")) or not (
        _is_plain_int(pending.get("version"))
    ):
        return False
    if pending["state"] != "pending" or pending["asset_id"] != asset_id:
        return False
    if pending["delta"] != delta:
        return False
    # 报告触发的提交在意图中随附达门槛报告 B（可选键）：崩溃恢复据此
    # 判定"报告事件 + 提交事件"两事件提交点是否完整。存在即须形状
    # 合法，否则无法安全对账。多源仲裁触发的提交另带 votes（随附
    # chain_vote 事件列表），存在即须为非空列表且每张票形状合法。
    report = intent.get("report")
    if report is not None and not chain_report_shape_ok(report):
        return False
    # 多源仲裁达 quorum 触发的提交另带可选键 vote（决定性 adopted 票
    # {source,report=B,state}）：崩溃恢复据此判定"票 + 报告 + 提交"
    # 三事件提交点是否完整。存在即须形状合法且为 adopted，否则无法
    # 安全对账。
    vote = intent.get("vote")
    if vote is not None:
        if not chain_vote_shape_ok(vote) or vote.get("state") != "adopted":
            return False
    # 跨链派发最终性结算触发的提交另带可选键 settle
    # （{"dispatch_id": D}）：崩溃恢复据此判定"chain_dispatch_settled
    # 与 asset_operation_committed"两事件提交点是否完整。存在即须
    # 恰含安全标识 dispatch_id，否则无法安全对账。
    settle = intent.get("settle")
    if settle is not None:
        if (
            not isinstance(settle, dict)
            or set(settle) != {"dispatch_id"}
            or not _valid_safe_id(settle.get("dispatch_id"))
        ):
            return False
    # 已结算派发链上重组的反向补偿提交另带可选键 reorg
    # （{"dispatch_id": D, "confirmation": V}）：补偿操作 D 在提交
    # 事务中**首次创建**（无 pending 前驱），崩溃回滚须把该操作整笔
    # 删除并恢复提交前资产快照，故 reorg 存在时不要求 pending 快照，
    # 但不得与 settle 共存。存在即须形状合法，否则无法安全对账。
    reorg = intent.get("reorg")
    if reorg is not None:
        if settle is not None:
            return False
        if (
            not isinstance(reorg, dict)
            or set(reorg) != {"dispatch_id", "confirmation"}
            or not _valid_safe_id(reorg.get("dispatch_id"))
            or not isinstance(reorg.get("confirmation"), dict)
        ):
            return False
        if pending is not None:
            return False
    else:
        if pending is None:
            return False
    if reorg is None:
        # pending 是创建时刻的操作快照 R，服务正常写入必带非布尔整数
        # balance/version；恢复据此还原操作，缺失即不可安全对账。
        if not _is_plain_int(pending.get("balance")) or not (
            _is_plain_int(pending.get("version"))
        ):
            return False
        if pending["state"] != "pending" or pending["asset_id"] != asset_id:
            return False
        if pending["delta"] != delta:
            return False
    old_balance = old_asset["balance"] if old_asset is not None else 0
    old_version = old_asset["version"] if old_asset is not None else 0
    return (
        new_balance == old_balance + delta
        and new_version == old_version + 1
    )

